import{z as B,x as p,o as s,c as A,q as l,j as o,D as t,d as E,s as n,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"顺序与因果一致性","description":"","frontmatter":{"title":"顺序与因果一致性","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sequential-causal-consistency.md","filePath":"cs/sequential-causal-consistency.md","lastUpdated":1791063341000}'),d={name:"cs/sequential-causal-consistency.md"};function u(m,a,c,D,C,f){const r=p("Mermaid");return s(),A("div",null,[a[2]||(a[2]=l('<h1 id="顺序与因果一致性" tabindex="-1">顺序与因果一致性 <a class="header-anchor" href="#顺序与因果一致性" aria-label="Permalink to &quot;顺序与因果一致性&quot;">​</a></h1><div class="epigraph"><p>顺序一致要有一个全局操作序，符合每进程程序序，但不须符合实时。因果一致只要求 happened-before 的写被看到的顺序不颠倒。</p><footer>—— 据 Lamport, How to Make a Multiprocessor Computer That Correctly Executes Multiprocess Programs, IEEE TC 1979；Ahamad et al., Causal Memory, 1995 整理</footer></div><p>上一课<a href="/cs/linearizability">线性一致性</a>把实时也算进顺序。缺口是<strong>更便宜的档</strong>：多核与广域复制常常放弃实时，只保留程序序或因果。本课不重画线性化点。后课最终一致还要再放弃「何时看到」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Lamport 顺序一致：存在全体操作的全序，每处理器上的程序序是该全序的子序，读看到的是该全序下最近的写。允许：实时上 A 已返回、B 才调用，历史仍把 B 排在 A 前——只要没人在中间用程序序钉住。这比线性一致弱，比「随便缓存」强。</p><p>因果一致（Ahamad 等因果内存）：若写 \\(w_1\\to w_2\\)（<a href="/cs/vector-clocks">向量时钟</a>的偏序，含程序序与同步），则任何读不能先看到 \\(w_2\\) 再看到 \\(w_1\\) 缺席的那种颠倒。并发写可以不同副本不同序。缺口：复制要在「全局全序」和「只保因果」之间选预算。</p><p><span class="marginnote">顺序一致没有线性一致的局部性：两个顺序一致对象并排放，组合不必顺序一致。因果常用版本向量或因果广播实现。</span></p><p><span class="marginnote">直觉类比：顺序一致像所有人看同一场直播——画面顺序全球一致，但不保证延迟一致；因果一致像聊天软件——你的回复必须排在被回复消息之后，而两条互不相干的消息在不同手机里谁先谁后无所谓。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现顺序一致：单总线、单日志、或每读拉全局屏障——贵。实现因果：写带依赖向量，读缓冲直到依赖到齐；或因果广播（Birman 等）。不要用 NTP 排序冒充因果。</p>',10)),(s(),o(i,null,{default:t(()=>[n(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20LIN%5B%22%E7%BA%BF%E6%80%A7%E4%B8%80%E8%87%B4%3A%20%E5%AE%9E%E6%97%B6%2B%E5%8E%9F%E5%AD%90%E7%82%B9%22%5D%20--%3E%20SEQ%5B%22%E9%A1%BA%E5%BA%8F%E4%B8%80%E8%87%B4%3A%20%E5%85%A8%E5%B1%80%E5%BA%8F%2B%E7%A8%8B%E5%BA%8F%E5%BA%8F%22%5D%0A%20%20SEQ%20--%3E%20CAU%5B%22%E5%9B%A0%E6%9E%9C%3A%20%E5%8F%AA%E4%BF%9D%20%E2%86%92%22%5D%0A%20%20CAU%20--%3E%20EV%5B%22%E6%9C%80%E7%BB%88%E4%B8%80%E8%87%B4%20%E5%90%8E%E8%AF%BE%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[E("PRAM（流水线内存）更弱：只保"),e("strong",null,"同一进程"),E("写的顺序，跨进程写可乱。本课点名，以免和因果混称。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"多核硬件提供的是更弱的模型（store buffer），靠 fence 升到需要的档——那是体系结构课的内存模型，本课只借用「档位」语言，不重写 store buffer。分布式里：从库异步 apply 常常连因果都破（先 apply 了无依赖的新写）。要因果，复制流必须按依赖或按单日志。",-1)),a[6]||(a[6]=e("p",null,"线性一致 ⇒ 顺序一致 ⇒ 因果一致，逆不成立。选档是给应用的承诺：锁的互斥通常要线性一致；协作编辑的插入因果可能够；计数器最终一致可能够。",-1)),a[7]||(a[7]=e("p",null,"上面那张图是档位阶梯；下面这张回答因果一致最关键的一条边——哪些顺序全副本必须一致、哪些允许分叉。",-1)),(s(),o(i,null,{default:t(()=>[n(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20P1%5B%22%E8%BF%9B%E7%A8%8B1%20%E5%86%99%20x%3D1%22%5D%20--%3E%20P2%5B%22%E8%BF%9B%E7%A8%8B2%20%E8%A7%81%E5%88%B0%20x%3D1%20%E5%90%8E%E5%86%99%20y%3D1%22%5D%0A%20%20P2%20--%3E%20C%5B%22%E5%9B%A0%E6%9E%9C%E8%BE%B9%20x%3D1%20%E2%86%92%20y%3D1%22%5D%0A%20%20C%20--%3E%20A%5B%22%E5%89%AF%E6%9C%ACA%20%E5%85%88%20x%3D1%20%E5%90%8E%20y%3D1%22%5D%0A%20%20C%20--%3E%20B%5B%22%E5%89%AF%E6%9C%ACB%20%E5%85%88%20x%3D1%20%E5%90%8E%20y%3D1%22%5D%0A%20%20W3%5B%22%E8%BF%9B%E7%A8%8B3%20%E5%B9%B6%E5%8F%91%E5%86%99%20z%3D1%22%5D%20-.-%3E%7C%22%E4%B8%8E%20x%3D1%20%E6%97%A0%E4%BE%9D%E8%B5%96%22%7C%20ZA%5B%22%E5%89%AF%E6%9C%ACA%20%E5%85%88%E6%94%B6%E5%88%B0%20z%20%E4%B9%9F%E5%90%88%E6%B3%95%22%5D%0A%20%20W3%20-.-%3E%20ZB%5B%22%E5%89%AF%E6%9C%ACB%20%E5%90%8E%E6%94%B6%E5%88%B0%20z%20%E4%B9%9F%E5%90%88%E6%B3%95%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=l('<p><span class="marginnote">数字实例：锁的两次获取必须分出唯一先后，要线性一致；聊天回复不能跑到原消息前面，因果一致够；点赞数少一票、下次刷新就回来，最终一致够。同一个系统里不同数据可以各选各的档。</span></p><p><span class="marginnote">常见误区：以为用 NTP 对齐机器时钟就得到因果序。实际上时钟偏差与闰秒调整会让「时间早」的写实际依赖「时间晚」的写；因果必须用依赖向量或版本向量显式记录，不能靠墙钟猜。</span></p><p>本课不把「因果一致」写成区块链的确认规则，也不写限价簿撮合序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写会话保证的六条（那是后课把因果再拆成客户端视角）。不引入 CRDT 合并。后课默认：放弃实时先落到顺序或因果；再放弃「所有人终见同一写集合的同一全序」就进最终一致。主备协议必须声明自己停在哪一档。</p><p>档位是历史集合，不是 QPS 数字。没有声明就没有正确性讨论。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>顺序一致：全局全序 + 程序序，不必实时。</li><li>因果一致：不颠倒 \\(a\\to b\\) 的写可见性；并发可分叉。</li><li>线性 ⇒ 顺序 ⇒ 因果；实现成本同向。</li><li>出处：Lamport, IEEE TC 1979；Ahamad et al., 1995。</li></ul>',8))])}const T=B(d,[["render",u]]);export{_ as __pageData,T as default};
